return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Idite na Plugin Search','Activate %s' => 'Aktiviraj %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> zahtijeva instaliranje i aktivaciju <strong>%2$s</strong> . <a href="%4$s">%3$s</a>','Enter your code here' => 'Unesite svoj kod ovdje','Add %s' => 'Dodaj %s','Remove' => 'Ukloniti','Order number and receipt will be sent to this email address.' => 'Broj narudžbe i račun bit će poslani na ovu adresu e-pošte.','Apartment, unit, building, floor, etc.' => 'Stan, jedinica, zgrada, kat itd.','Shipping phone' => 'Telefon za dostavu','Only used for shipping-related questions.' => 'Koristi se samo za pitanja u vezi s otpremom.','Single step' => 'Jedan korak','Click to go to the order summary' => 'Kliknite za odlazak na sažetak narudžbe','Cart total:' => 'Ukupna kolica:','Proceed to %s' => 'Nastavite do %s','Proceed to contact' => 'Nastavite s kontaktom','Proceed to shipping' => 'Nastavite s otpremom','Proceed to billing' => 'Nastavite s naplatom','Proceed to payment' => 'Prijeđite na plaćanje','Shipping method' => 'Način dostave','Additional notes' => 'Dodatne napomene','Payment method' => 'Način plaćanja','Step %1$s of %2$s' => 'Korak %1$s od %2$s','Change: %s' => 'Promjena: %s','Not selected yet.' => 'Još nije odabrano.','Same as shipping address' => 'Isto kao adresa za dostavu','Same as billing address' => 'Isto kao adresa za naplatu','Order summary' => 'Sažetak narudžbe','Edit cart' => 'Uredi košaricu','Did you mean %s?' => 'Jeste li mislili %s?','Change email address to: {suggestion-value}' => 'Promijeni adresu e-pošte u: {suggestion-value}','This is a required field.' => 'Ovo je obavezno polje.','This is not a valid email address.' => 'Ovo nije važeća adresa e-pošte.','This field does not match the related field value.' => 'Ovo polje ne odgovara vrijednosti povezanog polja.','The CPF number "{cpf_number}" is invalid.' => 'CPF broj &quot;{cpf_number}&quot; nije valjan.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ broj &quot;{cnpj_number}&quot; je nevažeći.','(Required)' => '(Potreban)','Checkout Header - Desktop' => 'Checkout Header - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Prikaži widgete u zaglavlju naplate za velike zaslone. Prikazuje se samo ako se koristi zaglavlje za naplatu dodatka.','Checkout Header - Mobile' => 'Checkout Header - Mobile','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Prikaz widgeta ispod zaglavlja za naplatu za mobilne uređaje. Prikazuje se samo ako se koristi zaglavlje za naplatu dodatka.','Checkout Sidebar' => 'Bočna traka za plaćanje','Display widgets on the checkout sidebar after the order summary.' => 'Prikaži widgete na bočnoj traci naplate nakon sažetka narudžbe.','Checkout Order Summary' => 'Checkout Sažetak narudžbe','Display widgets inside the order summary at the checkout page.' => 'Prikaz widgeta unutar sažetka narudžbe na stranici za naplatu.','Checkout Below Place Order' => 'Plaćanje Ispod Naruči','Display widgets below the place order button at the checkout page.' => 'Prikaži widgete ispod gumba za naručivanje na stranici za naplatu.','Checkout Footer' => 'Podnožje naplate','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Prikaži widgete u podnožju naplate. Prikazuje se samo ako se koristi podnožje za naplatu dodatka.','Classic' => 'klasična','Boxed' => 'U kutiji','Split' => 'Split','Minimalist' => 'Minimalistički','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Dodaci Fluid Checkout i Delivery Date by CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Otkrili smo da koristite dodatke Delivery &amp; Pickup Date Time za WooCommerce (besplatan i PRO) tvrtke CodeRockz. Integracija s ovim dodacima premještena je u Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Nadogradite na PRO','Fluid Checkout database updated successfully' => 'Baza podataka Fluid Checkout uspješno je ažurirana','The database changes where applied successfully.' => 'Baza podataka se mijenja tamo gdje je uspješno primijenjena.','Dismiss' => 'Odbaciti','Fluid Checkout database update' => 'Ažuriranje baze podataka Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Potrebne su neke izmjene u bazi podataka. Kao i kod svakog ažuriranja, preporučujemo vam da <strong>napravite potpunu sigurnosnu kopiju svoje web stranice prije nastavka</strong> .','Update database' => 'Ažurirajte bazu podataka','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nije kompatibilan s izgledom plaćanja Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout treba klasičnu WooCommerce formu za naplatu temeljenu na kratkom kodu kako bi funkcionirao. Kada koristite Divi Builder za prilagodbu izgleda i dojma stranice za naplatu, klasični kratki kodovi zamjenjuju se prilagođenim widgetima iz Divi Buildera za svaki dio stranice za naplatu. Ovi prilagođeni widgeti nisu kompatibilni s Fluid Checkout-om.</p><p> Uredite svoju stranicu za naplatu i zamijenite widgete Divi Builder s tekstualnim widgetom koji sadrži kratki kod <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Uredite stranicu za naplatu','Read the documentation.' => 'Pročitajte dokumentaciju.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanizirana PRO značajka plaćanja u više koraka mora biti onemogućena kada se koristi Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kada koristite Fluid Checkout, značajka u više koraka iz germaniziranog PRO dodatka postaje nepotrebna i može uzrokovati <strong>kritične pogreške tijekom obrade novih narudžbi</strong> . Onemogućite značajku germanizirane PRO višestruke naplate u postavkama dodatka.','Go to Germanized settings' => 'Idite na germanizirane postavke','Thanks for choosing Fluid Checkout!' => 'Hvala što ste odabrali Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Već neko vrijeme koristite dodatak. Kako vam se do sada sviđa?<br> Dajte nam brzu ocjenu, cijenimo svaku povratnu informaciju i to nas potiče da nastavimo poboljšavati dodatak :)','Rate the plugin' => 'Ocijenite dodatak','I need help!' => 'Trebam pomoć!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Neke značajke WooCommerce Checkout Managera tvrtke Quadlayers možda neće raditi kako se očekuje kada ga koristite s Fluid Checkoutom. Pročitajte <a href="%s">našu dokumentaciju</a> za više informacija i alternativna rješenja.','Read documentation' => 'Pročitajte dokumentaciju','Don\'t show this again' => 'Ne prikazuj ovo više','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Više predložaka dizajna','Optimized cart page' => 'Optimizirana stranica košarice','Optimized order received / thank you page' => 'Primljena optimizirana narudžba / stranica zahvale','Edit cart contents at checkout page' => 'Uredite sadržaj košarice na stranici za naplatu','Account matching / user matching' => 'Uparivanje računa/uparivanje korisnika','Trust symbols on the cart and thank you pages' => 'Simboli povjerenja na stranicama košarice i zahvale','More positions for the coupon code on the checkout page' => 'Više pozicija za kod kupona na stranici za naplatu','International phone numbers' => 'Međunarodni telefonski brojevi','Gift messages and packing slips' => 'Poruke s poklonima i otpremnice','Local pickup and in-store collection' => 'Lokalno preuzimanje i preuzimanje u trgovini','EU-VAT Assistant' => 'EU-PDV asistent','I already have it – Hide this offer' => 'Već ga imam – Sakrij ovu ponudu','Activated' => 'Aktiviran','Address book' => 'Adresar','Select an image' => 'Odaberite sliku','Cart layout' => 'Izgled kolica','Cart optimizations' => 'Optimizacije košarica','Enable cart page optimizations' => 'Omogući optimizaciju stranice košarice','Header and footer template' => 'Predložak zaglavlja i podnožja','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrolira hoće li se koristiti zaglavlje i podnožje stranice bez ometanja ili zadržati zaglavlje i podnožje trenutno aktivne teme.','Distraction free header and footer' => 'Zaglavlje i podnožje bez ometanja','Theme\'s header and footer' => 'Zaglavlje i podnožje teme','Cart elements' => 'Elementi kolica','Make the order summary stay visible on the cart page while scrolling' => 'Neka sažetak narudžbe ostane vidljiv na stranici košarice tijekom pomicanja','Coupon codes' => 'Kodovi kupona','Hidden' => 'Skriven','Before the cart items section' => 'Prije odjeljka stavki u košarici','Inside the cart items section' => 'Unutar odjeljka stavki u košarici','After the cart items section' => 'Nakon odjeljka stavki u košarici','Before the shipping section' => 'Prije odjeljka za otpremu','After the shipping section' => 'Nakon odjeljka za otpremu','Before the order summary' => 'Prije sažetka narudžbe','Inside the order summary' => 'Unutar sažetka narudžbe','Before the order totals' => 'Prije ukupnog iznosa narudžbe','After the order totals' => 'Nakon što narudžba zbroji','After the order summary' => 'Nakon sažetka narudžbe','Shipping' => 'Dostava','Select position where to display the shipping costs and calculator on the cart page.' => 'Odaberite mjesto gdje želite prikazati troškove dostave i kalkulator na stranici košarice.','Display as a cart section' => 'Prikaz kao dio košarice','Cross-sells' => 'Unakrsna prodaja','Select position where to display the cross-sells section on the cart page.' => 'Odaberite poziciju na kojoj želite prikazati odjeljak dodatne prodaje na stranici košarice.','Before the cart actions' => 'Prije akcija kolica','After the cart actions' => 'Nakon akcija kolica','Layout of cross-sell items on the cart page.' => 'Izgled artikala dodatne prodaje na stranici košarice.','Optimized horizontal cross-sells layout' => 'Optimiziran horizontalni izgled za unakrsnu prodaju','Theme\'s cross-sells layout' => 'Izgled teme za unakrsnu prodaju','Number of cross-sell items to display on the cart page' => 'Broj artikala dodatne prodaje za prikaz na stranici košarice','Add widget areas to the cart page' => 'Dodajte područja widgeta na stranicu košarice','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ova područja widgeta koriste se za dodavanje simbola povjerenja i znački povjerenja na stranicu košarice.','Checkout' => 'Odjava','Checkout layout' => 'Izgled blagajne','Design template' => 'Predložak dizajna','Dark mode' => 'Tamni način rada','Enable dark mode' => 'Omogući tamni način rada','Logo image' => 'Slika logotipa','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Odaberite sliku koja će se prikazati u zaglavlju stranice za naplatu. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','Header background color' => 'Boja pozadine zaglavlja','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Odaberite boju pozadine za zaglavlje stranice za naplatu. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','HTML color value. ie: #f3f3f3' => 'HTML vrijednost boje. tj.: #f3f3f3','Page background color' => 'Boja pozadine stranice','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Odaberite boju pozadine za stranicu za naplatu. Boja se nanosi na element <em>tijela</em> .','Footer background color' => 'Boja pozadine podnožja','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Odaberite boju pozadine za podnožje stranice za naplatu. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','Progress bar' => 'Traka napretka','Display the checkout progress bar when using multi-step checkout layout' => 'Prikažite traku napretka naplate kada koristite raspored naplate u više koraka','Make the checkout progress bar stay visible while scrolling' => 'Neka traka napretka naplate ostane vidljiva tijekom pomicanja','Express checkout' => 'Ekspresna naplata','Enable the express checkout section' => 'Omogućite odjeljak brze naplate','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Prikazuje odjeljak za brzu naplatu pri naplati kada podržani pristupnici plaćanja imaju ovu značajku omogućenu.','Display express checkout buttons in one line for larger screens' => 'Prikažite gumbe za brzu naplatu u jednom retku za veće zaslone','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Zanemarite dodatna obavezna polja za naplatu kada plaćate putem kompatibilnog pristupnika za brzu naplatu','Make the order summary stay visible while scrolling' => 'Neka sažetak narudžbe ostane vidljiv tijekom pomicanja','Choose a background color for the order summary section.' => 'Odaberite boju pozadine za odjeljak sažetka narudžbe.','Highlight the order totals row in the order summary table' => 'Označite redak s ukupnim iznosom narudžbe u tablici sažetka narudžbe','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Najkorisnije kada odjeljak sažetka narudžbe nema istaknutu boju pozadine. Također se može primijeniti na stranice Košarica, Primljena narudžba i Prikaz narudžbe kada koristite Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Poveznica za akciju na sažetku narudžbe na blagajni.','Edit cart link' => 'Uredi vezu za košaricu','Cart items count' => 'Broj stavki u košarici','Link to shop page' => 'Link na stranicu trgovine','Cart items' => 'Stavke u košarici','Hide cart items errors at the checkout page' => 'Sakrij pogreške stavki košarice na stranici za naplatu','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Nemojte prikazivati poruku o pogrešci stavki košarice na vrhu stranice za naplatu. Prilikom podnošenja obrasca za naplatu radi dovršetka kupnje, ove će se poruke o pogrešci uvijek prikazivati.','Place order' => 'Pošaljite narudžbu','Define the position to display "Place order" and terms checkbox section.' => 'Definirajte položaj za prikaz odjeljka potvrdnog okvira &quot;Postavi narudžbu&quot; i uvjete.','Some options might not be compatible with some plugins and themes.' => 'Neke opcije možda neće biti kompatibilne s nekim dodacima i temama.','Below the payment section' => 'Ispod odjeljka za plaćanje','Below the order summary' => 'Ispod sažetka narudžbe','Both below the payment section and the order summary' => 'I ispod odjeljka plaćanja i sažetka narudžbe','Add widget areas to the checkout page' => 'Dodajte područja widgeta na stranicu za naplatu','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ova područja widgeta koriste se za dodavanje simbola povjerenja i znački povjerenja na stranicu za naplatu.','Display the coupon codes section title' => 'Prikaži naslov odjeljka s kodovima kupona','Select position where to display the coupon codes section on the checkout page.' => 'Odaberite mjesto gdje će se prikazati odjeljak s kodovima kupona na stranici za naplatu.','Before the checkout steps' => 'Prije koraka naplate','As a substep before payment methods' => 'Kao podkorak prije načina plaćanja','As a substep after payment methods' => 'Kao podkorak nakon načina plaćanja','Default button style' => 'Zadani stil gumba','"Add" link button' => 'Gumb za vezu &quot;Dodaj&quot;.','Checkout fields' => 'Polja za naplatu','Optional fields' => 'Neobavezna polja','Hide optional fields behind a link button' => 'Sakrij izborna polja iza gumba veze','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Preporuča se držati ovu opciju označenom kako biste smanjili broj otvorenih polja za unos, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">pročitajte istraživanje</a> .','Do not hide "Address line 2" fields behind a link button' => 'Nemojte skrivati polja &quot;Adresa redak 2&quot; iza gumba veze','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Preporučuje se samo kada većina kupaca zaista treba polje &quot;Adresa red 2&quot; ili kada je dobivanje točne adrese za dostavu presudno (tj. ako se dostavlja hrana i drugi kvarljivi proizvodi).','Billing address' => 'Adresa za naplatu','Select position where to display the billing address section on the checkout page.' => 'Odaberite mjesto gdje želite prikazati odjeljak s adresom za naplatu na stranici za naplatu.','As a step before shipping' => 'Kao korak prije otpreme','As a sub-step before the shipping address section' => 'Kao pod-korak prije odjeljka s adresom za dostavu','As a sub-step after the shipping address section' => 'Kao podkorak nakon odjeljka s adresom za dostavu','As a step after shipping' => 'Kao korak nakon otpreme','As a sub-step before the payment section' => 'Kao podkorak prije odjeljka plaćanja','Force billing and shipping addresses to the same (single section)' => 'Prisilno na iste adrese za naplatu i dostavu (jedan odjeljak)','Checkbox for "Same as shipping/billing address" checked by default' => 'Potvrdni okvir za &quot;Isto kao adresa za dostavu/naplatu&quot; označen prema zadanim postavkama','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Potvrdni okvir &quot;Isto kao adresa za dostavu&quot; počet će označen prema zadanim postavkama kada se prvo prikaže odjeljak s adresom za dostavu.<br> Potvrdni okvir &quot;Isto kao adresa za naplatu&quot; počet će označen prema zadanim postavkama kada se prvo prikaže odjeljak s adresom za naplatu.<br> Preporučljivo je ostaviti ovu opciju označenom kako bi se značajno smanjio broj otvorenih polja za unos prilikom naplate, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">pročitajte istraživanje</a> .','Highlight the billing address section in the checkout form' => 'Istaknite odjeljak adrese za naplatu u obrascu za naplatu','Shipping address' => 'Adresa za dostavu','Highlight the shipping address section in the checkout form' => 'Označite odjeljak adrese za dostavu u obrascu za naplatu','Shipping methods' => 'Načini dostave','Choose in which position to display the shipping methods section.' => 'Odaberite na kojoj poziciji želite prikazati odjeljak s načinima dostave.','Before shipping address' => 'Adresa prije dostave','After shipping address' => 'Nakon adrese za dostavu','Local pickup' => 'Lokalno preuzimanje','Removes shipping address section when a local pickup shipping method is selected.' => 'Uklanja odjeljak s adresom za dostavu kada je odabran lokalni način dostave.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Zamjenjuje adresu dostave lokacijom mjesta preuzimanja kada je odabran lokalni način dostave preuzimanja.','Choose which address to save as the shipping address for local pickup orders.' => 'Odaberite koju adresu želite spremiti kao adresu za dostavu za lokalne narudžbe za preuzimanje.','Save the selected pickup location' => 'Spremite odabrano mjesto preuzimanja','Save same as the billing address' => 'Spremi isto kao adresu za naplatu','Do not save any shipping address' => 'Ne spremajte nijednu adresu za dostavu','Company name field for shipping address' => 'Polje za naziv tvrtke za adresu za dostavu','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Promijenite vidljivost polja s nazivom tvrtke za odjeljak adrese za dostavu na obrascu za naplatu.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ako je polje postavljeno kao &quot;izborno&quot;, što je zadano stanje vidljivosti, neće se primijeniti nikakve promjene kako bi drugi dodaci mogli primijeniti promjene koje su im potrebne.','Hidden (remove field)' => 'Skriveno (ukloni polje)','Optional' => 'Neobavezno','Required' => 'Potreban','Add shipping phone field to the checkout form.' => 'Dodajte polje telefona za dostavu u obrazac za naplatu.','Choose in which step to display the shipping phone field.' => 'Odaberite u kojem koraku želite prikazati polje telefona za otpremu.','Contact step' => 'Kontaktni korak','Billing phone' => 'Telefon za naplatu','Add billing phone field to the checkout form.' => 'Dodajte polje telefona za naplatu u obrazac za naplatu.','Choose in which step to display the billing phone field.' => 'Odaberite u kojem koraku želite prikazati polje telefona za naplatu.','Show country code beside the flag' => 'Prikaži kod zemlje pored zastave','Show an example of a valid phone number inside phone fields' => 'Pokažite primjer važećeg telefonskog broja u telefonskim poljima','Do not change placeholders' => 'Nemojte mijenjati rezervirana mjesta','Show if not defined' => 'Prikaži ako nije definirano','Always show' => 'Uvijek pokaži','Order notes' => 'Bilješke o narudžbi','Define the visibility of the additional order notes field.' => 'Definirajte vidljivost polja dodatnih napomena o narudžbi.','Gift options' => 'Mogućnosti darova','Allow customers to add a gift message and other gift related options to the order.' => 'Omogućite kupcima da narudžbi dodaju poruku o poklonu i druge opcije vezane uz dar.','Display the gift message as part of the order details table instead of a separate section' => 'Prikažite poruku o poklonu kao dio tablice s detaljima narudžbe umjesto zasebnog odjeljka','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ova opcija utječe na stranicu s potvrdom narudžbe (stranica sa zahvalom) i pojedinosti narudžbe na stranicama računa, e-poštom i potvrdama o pakiranju.','Account matching' => 'Podudaranje računa','Enable the account matching feature' => 'Omogućite značajku podudaranja računa','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Povežite narudžbe kupca gosta s njegovim postojećim računom kada već postoji račun s podacima za kontakt kupca.','Display message when an account exists with the email address provided' => 'Prikaži poruku kada postoji račun s navedenom adresom e-pošte','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Zamjenjuje polja za kreiranje računa s obavijesti i opcijom za prijavu. U nekim kontekstima može se preporučiti da ovu opciju ostavite onemogućenom kako biste zaštitili privatnost kupaca.','Dashboard' => 'Nadzorna ploča','Integrations' => 'Integracije','License keys' => 'Ključevi licence','Visit our website for more information about our plugins and add-ons.' => 'Posjetite našu web stranicu za više informacija o našim dodacima i dodacima.','Order pay page' => 'Stranica za plaćanje narudžbe','Order pay' => 'Plaćanje naloga','Enable order pay page optimizations' => 'Omogući optimizaciju stranice za plaćanje narudžbi','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Mijenja izgled stranice za plaćanje narudžbi za postojeće narudžbe koje čekaju plaćanje od strane kupca.','Add widget areas to the order pay page' => 'Dodajte područja widgeta na stranicu za plaćanje narudžbe','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Ova područja widgeta koriste se za dodavanje simbola povjerenja i značaka povjerenja na stranicu za plaćanje narudžbe.','Thank you page & order details layout' => 'Izgled stranice sa zahvalom i pojedinosti o narudžbi','Order details optimizations' => 'Optimizacija detalja narudžbe','Enable thank you page and order details optimizations' => 'Omogućite stranicu zahvale i optimizaciju pojedinosti narudžbe','Changes the layout of order details on the thank you page and account pages.' => 'Mijenja izgled detalja narudžbe na stranici zahvale i stranicama računa.','Enable order details customizations on email notifications' => 'Omogućite prilagodbe pojedinosti narudžbe u obavijestima e-poštom','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Prikaz novih odjeljaka i promjena redoslijeda odjeljaka u obavijestima putem e-pošte. Stilovi detalja narudžbe u obavijestima e-poštom ostaju nepromijenjeni.','Thank you page' => 'Hvala stranica','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Ove opcije utječu na stranicu zahvale, poznatu i kao stranice primljene narudžbe ili stranice potvrde narudžbe.','Order details layout' => 'Izgled detalja narudžbe','Display the order details with wide layout on the thank you page' => 'Prikažite pojedinosti narudžbe širokim rasporedom na stranici zahvale','Add widget areas to the thank you page' => 'Dodajte područja widgeta na stranicu zahvale','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ova područja widgeta koriste se za dodavanje simbola povjerenja i znački povjerenja na stranicu zahvale.','Order actions' => 'Radnje naloga','Choose in which position to display the order actions.' => 'Odaberite na kojoj poziciji želite prikazati radnje naloga.','Inside the order overview' => 'Unutar pregleda narudžbi','After the order overview' => 'Nakon pregleda narudžbi','After order sections' => 'Nakon narudžbe odjeljaka','Order status' => 'Status narudžbe','Display the order status progress bar' => 'Prikaz trake statusa narudžbe','Choose in which position to display the section.' => 'Odaberite na kojoj poziciji želite prikazati odjeljak.','After the order overview and payment instructions' => 'Nakon pregleda narudžbe i instrukcija za plaćanje','Before the order items section' => 'Prije odjeljka stavki narudžbe','Inside the order items section' => 'Unutar odjeljka stavki narudžbe','After the order items section' => 'Nakon odjeljka stavke narudžbe','On the sidebar' => 'Na bočnoj traci','Order downloads' => 'Naručite preuzimanja','Gift message' => 'Poklon poruka','Tools' => 'Alati','Troubleshooting' => 'Rješavanje problema','Debug options' => 'Opcije otklanjanja pogrešaka','Debug mode' => 'Način otklanjanja pogrešaka','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Korištenje načina otklanjanja pogrešaka utječe na performanse web stranice. Koristite ovu opciju samo tijekom rješavanja problema.','Load unminified assets' => 'Učitaj neminificirana sredstva','Enhanced select fields' => 'Poboljšana polja za odabir','Fix automatic zoom-in on form fields' => 'Popravite automatsko povećavanje polja obrasca','Set <code>font-size</code> inside form fields to 16px' => 'Postavite <code>font-size</code> unutar polja obrasca na 16 px','Fluid Checkout' => 'Naplata tekućine','Settings' => 'postavke','Support' => 'podrška','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Nadogradite na PRO</a> da otključate više opcija.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentalno)','Please verify your phone number.' => 'Molimo potvrdite svoj telefonski broj.','The Bluehost Plugin' => 'Bluehost dodatak','Custom fields' => 'Prilagođena polja','Enable custom shipping email field' => 'Omogući prilagođeno polje e-pošte za dostavu','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kada je omogućeno, polje e-pošte za dostavu iz dodatka Bluehost bit će dodano u obrazac za naplatu.','Captcha Pro by BestWebSoft' => 'Captcha Pro tvrtke BestWebSoft','Captcha position' => 'Captcha pozicija','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definirajte položaj za prikaz captcha odjeljka. Neke pozicije možda neće raditi ovisno o odabranoj vrsti captcha.','Selecting a pickup point is required before proceeding.' => 'Prije nastavka potrebno je odabrati mjesto preuzimanja.','Pickup point' => 'Mjesto preuzimanja','Pickup point not selected yet.' => 'Mjesto preuzimanja još nije odabrano.','Pickup point:' => 'Mjesto preuzimanja:','Mailchimp for WooCommerce' => 'Mailchimp za WooCommerce','Subscribe checkbox' => 'Potvrdni okvir za pretplatu','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Nadjačajte poziciju za potvrdni okvir za pretplatu na stranici za naplatu i uvijek ga prikazujte na koraku kontakta','Before Shipping Address' => 'Prije adrese za dostavu','(originally "%s")' => '(izvorno &quot;%s&quot;)','After Shipping Address' => 'Nakon adrese za dostavu','Selecting a collection point is required when shipping with FermoPoint.' => 'Prilikom slanja s FermoPointom potrebno je odabrati sabirno mjesto.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ako je označeno, obavještava korisnike o pogreškama pri upisu u e-pošti. (Ova značajka je onemogućena jer Fluid Checkout nudi značajku. Promjene ove opcije neće stupiti na snagu)','Enable Mail Check: (disabled feature)' => 'Omogući provjeru pošte: (onemogućena značajka)','Carrier:' => 'Prijevoznik:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce marketing putem e-pošte','Sign up checkbox position' => 'Pozicija potvrdnog okvira za prijavu','Move the sign up checkbox to the contact step' => 'Pomaknite potvrdni okvir prijave na korak kontakta','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kada je omogućeno, potvrdni okvir će se premjestiti na korak kontakta neovisno o lokaciji prikaza definiranoj u postavkama dodatka Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Napredak naplate','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Označite odjeljak koraka naplate iz Bethemea na stranicama naplate, košarice i primljene narudžbe.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Krušne mrvice','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Ispišite odjeljak s mrvicama iz teme Fennik kada koristite zaglavlje i podnožje Fluid Checkout.','Theme Go' => 'Tema Go','My account layout' => 'Izgled mog računa','Enable wide layout on "My account" page.' => 'Omogućite široki izgled na stranici &quot;Moj račun&quot;.','Theme Impreza' => 'Tema Impreza','Header' => 'Zaglavlje','Spacing for site header at the checkout page (in pixels)' => 'Razmak za zaglavlje stranice na stranici za naplatu (u pikselima)','Only applicable when using the Impreza theme header at the checkout page.' => 'Primjenjivo samo kada koristite zaglavlje teme Impreza na stranici za naplatu.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak koraka naplate iz teme Kapee na stranicama naplate, košarice i primljene narudžbe.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak koraka naplate iz teme Porto na stranicama naplate, košarice i primljene narudžbe.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak koraka naplate iz teme Pressmart na stranicama naplate, košarice i primljene narudžbe.','Theme The Gem' => 'Tema Dragulj','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Ispišite odjeljak koraka naplate iz teme The Gem kada koristite zaglavlje i podnožje Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Ispišite odjeljak koraka naplate iz teme Woodmart kada koristite zaglavlje i podnožje Fluid Checkout.','Checkout options' => 'Mogućnosti naplate','Disable the theme checkout options' => 'Onemogućite opcije provjere teme','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Opcije prikaza slike proizvoda, polja količine, gumba za uklanjanje i poveznice na stranicu proizvoda dodane temom onemogućene su prema zadanim postavkama.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Napredak narudžbe','Display order progress from the theme' => 'Prikaz napretka narudžbe iz teme','Display the form field labels visible on the page' => 'Prikažite oznake polja obrasca vidljive na stranici','It is recommended to keep this option enabled for a better user experience.' => 'Preporučljivo je držati ovu opciju uključenom radi boljeg korisničkog iskustva.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Dodajte dodatna polja u obrazac za naplatu','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Dodaje dodatnu e-poštu za dostavu i polje telefona za dostavu u odjeljak s adresom za dostavu.','Go to the home page' => 'Idite na početnu stranicu','Skip to content' => 'Preskoči na sadržaj','Create an account' => 'Napravi račun','Log in to your account' => 'Prijavite se na svoj račun','Already have an account?' => 'Već imate račun?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Prijavljeni ste kao %1$s. <a href="%2$s">Odjavi se</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Vaša narudžba ima ukupni iznos od %s. Daljnje plaćanje nije potrebno.','Close and continue with checkout' => 'Zatvorite i nastavite s naplatom','Continue' => 'Nastaviti','Parcel terminal' => 'Paketni terminal','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ovaj widget je zamijenjen Fluid Checkout-om.</p><p> Kada koristite Fluid Checkout, stranica za naplatu mora koristiti izvorni WooCommerce kratki kod <code>[woocommerce_checkout]</code> kako bi ispravno radila.</p><p> Za više informacija posjetite dokumentaciju Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Dodatni odjeljci zaglavlja','Output additional header sections if enabled in the theme settings.' => 'Ispis dodatnih odjeljaka zaglavlja ako je omogućeno u postavkama teme.','More information' => 'Više informacija','Pick a Locker' => 'Odaberite ormarić','Page template' => 'Predložak stranice','Use `Order confirmation` page template for block-based themes' => 'Koristite predložak stranice `Potvrda narudžbe` za teme temeljene na blokovima','Only applies when using a block-based theme.' => 'Primjenjuje se samo pri korištenju teme temeljene na blokovima.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Obrazac za plaćanje','Apply styles to the Stripe payment form fields' => 'Primjena stilova na polja Stripe obrasca za plaćanje','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kada je omogućeno, Fluid Checkout će primijeniti stilove optimizirane za kompatibilnost s dodatkom. Možda biste trebali onemogućiti ovu opciju ako koristite prilagođene stilove za polja Stripe obrasca za plaćanje.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Ispišite odjeljak koraka naplate iz Nyture teme kada koristite Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Omogućuje kupcima plaćanje za narudžbe koje je ručno kreirao administrator trgovine ili nisu dovršene tijekom plaćanja.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Dodatak WooCommerce Checkout Manager tvrtke Quadlayers nije kompatibilan s Fluid Checkoutom.','Company name field for billing address' => 'Polje za naziv tvrtke za adresu za naplatu','Change visibility for the company name field for the billing address section on the checkout form.' => 'Promijenite vidljivost polja naziva tvrtke za odjeljak adrese za naplatu na obrascu za naplatu.','Theme Bookshelf' => 'Tematska polica za knjige','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Ispišite odjeljak s koracima naplate iz teme Bookshelf kada koristite Fluid Checkout.','Account password' => 'Lozinka računa','An account will be created with the information provided at checkout when completing the order.' => 'Prilikom narudžbe, s podacima navedenima prilikom plaćanja, bit će kreiran račun.','Choose the style of the progress bar.' => 'Odaberite stil trake napretka.','Bars' => 'Barovi','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Izgled WooCommerce stranice','Force wide layout on WooCommerce pages' => 'Nametnite široki raspored na WooCommerce stranicama','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'To osigurava da odjeljak sadržaja nije preuzak na WooCommerce stranicama, uključujući stranice za naplatu, košaricu, primljenu narudžbu, plaćanje narudžbe i račun.','WooCommerce Smart Coupons' => 'WooCommerce pametni kuponi','Position on checkout page' => 'Pozicija na stranici za naplatu','Choose where to display the available coupons section on the checkout page.' => 'Odaberite gdje će se na stranici za plaćanje prikazati odjeljak dostupnih kupona.','Before the progress bar' => 'Prije trake napretka','After the progress bar' => 'Nakon trake napretka','Before coupon codes section' => 'Prije odjeljka s kodovima kupona','Format phone numbers according to the rules for each country.' => 'Formatirajte telefonske brojeve prema pravilima za svaku zemlju.','Use precise phone number validation' => 'Koristite preciznu validaciju telefonskog broja','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ovo je eksperimentalna značajka i možda neće raditi kako se očekuje u svim postavkama. Koristite je s oprezom.','Phone number validation types used when precise validation is enabled.' => 'Vrste validacije telefonskog broja koje se koriste kada je omogućena precizna validacija.','Mobile' => 'Mobilni uređaj','Fixed line' => 'Fiksna linija','Toll free' => 'Besplatni poziv','Or' => 'Ili','Contact' => 'Kontakt','Multi step' => 'Više koraka','2 columns' => '2 stupca','1 column' => '1 stupac','Before checkout steps' => 'Koraci prije plaćanja','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Prilikom korištenja izgleda blagajne <em>&quot;1 stupac&quot;</em> ova je opcija uvijek postavljena na <em>&quot;Prije koraka blagajne&quot;</em> i primjenjuje se i na prikaz za stolna računala.','Position for the extra order summary section on mobile.' => 'Pozicija za dodatni odjeljak sažetka narudžbe na mobilnom uređaju.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Opcija <em>&quot;Na zaglavlju web-mjesta&quot;</em> primjenjuje se samo kada se koristi zaglavlje bez ometanja.','On the site header (requires distraction-free header)' => 'U zaglavlju stranice (potreban je zaglavlje bez ometanja)','Initial state for the expansible order summary section on mobile.' => 'Početno stanje za proširivi odjeljak sažetka narudžbe na mobilnom uređaju.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Preporučujemo da ga postavite kao <em>proširenog</em> za sljedeće zemlje zbog regulatornih zahtjeva: <strong>Njemačku</strong> , <strong>Austriju</strong> , <strong>Švicarsku</strong> , <strong>Nizozemsku</strong> , <strong>Poljsku</strong> , <strong>Belgiju</strong> i <strong>Francusku</strong> .','Collapsed' => 'Sažeto','Expanded' => 'Prošireno','Do not show' => 'Ne prikazuj','yes' => 'Da','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za broj telefona za dostavu može biti &quot;obavezno&quot; ako se odjeljak s adresom za naplatu prikazuje nakon odjeljka s adresom za dostavu, a polje za broj telefona za naplatu postavljeno je kao &quot;obavezno&quot;. To je potrebno kako bi se osiguralo da se adresa za dostavu može kopirati na adresu za naplatu kada je ta opcija označena, inače kupac možda neće moći dovršiti obrazac za naplatu.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za telefonski broj za naplatu može biti &quot;obavezno&quot; ako se odjeljak s adresom za naplatu prikazuje prije odjeljka s adresom za dostavu, a polje za telefonski broj za dostavu postavljeno je kao &quot;obavezno&quot;. To je potrebno kako bi se osiguralo da se adresa za dostavu može kopirati na adresu za naplatu kada je ta opcija označena, inače kupac možda neće moći dovršiti obrazac za naplatu.','Settings profiles' => 'Profili postavki','Settings profile' => 'Postavke profila','You do not have permission to perform this action.' => 'Nemate dopuštenje za izvođenje ove radnje.','You do not have permission to activate plugins.' => 'Nemate dopuštenje za aktiviranje dodataka.','Missing plugin.' => 'Nedostaje dodatak.','Plugin activated.' => 'Dodatak je aktiviran.','The following changes will be applied:' => 'Primijenit će se sljedeće promjene:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Od verzije Fluid Checkout 5.0, postavke se spremaju drugačije. Stare opcije se i dalje pohranjuju u bazi podataka kako bi se omogućio povratak na prethodne verzije ako je potrebno.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Vaša trgovina već oko 2 tjedna radi s novim postavkama kako biste mogli očistiti naslijeđene opcije pohranjene u bazi podataka. Imajte na umu da će nakon čišćenja, ako se trebate vratiti na prethodne verzije dodatka, koristiti zadane vrijednosti za sve postavke.','Fluid Checkout settings cleanup' => 'Čišćenje postavki Fluid Checkout-a','Delete leftover options' => 'Izbriši preostale opcije','Help us improve Fluid Checkout' => 'Pomozite nam poboljšati Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Dijelite anonimna izvješća o okruženju web-mjesta s Fluid Checkoutom kako biste dobili bržu podršku i pomogli nam poboljšati kompatibilnost i izmjeriti utjecaj. Nisu uključeni podaci o kupcima, korisnicima ili osjetljivi podaci. U postavkama Alata možete odabrati što će se dijeliti u bilo kojem trenutku.','Enable site environment reports' => 'Omogući izvješća o okruženju web-mjesta','Review settings' => 'Pregled postavki','This preview has expired. Reload the admin page to start a new preview.' => 'Ovaj je pregled istekao. Ponovno učitajte administratorsku stranicu da biste započeli novi pregled.','Preview expired' => 'Pregled je istekao','Orders cannot be placed in the preview.' => 'Narudžbe se ne mogu izvršiti u pregledu.','Logging in is not available in the preview.' => 'Prijava nije dostupna u pregledu.','Accounts cannot be created in the preview.' => 'Računi se ne mogu kreirati u pregledu.','Requests to other sites are blocked in the preview.' => 'Zahtjevi prema drugim web-lokacijama blokirani su u pregledu.','Processing…' => 'Obrada…','Something went wrong. Please try again.' => 'Nešto je pošlo po zlu. Pokušajte ponovno.','Activate plugin' => 'Aktiviraj dodatak','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Potpuni paket za naplatu','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Sve PRO značajke + svi dodaci, jedna cijena. Predlošci dizajna, optimizirane stranice košarice i primljenih narudžbi, usklađivanje računa i još mnogo toga.','Optimized order pay page' => 'Optimizirana stranica za plaćanje narudžbe','Express checkout buttons from supported payment methods' => 'Gumbi za brzu naplatu iz podržanih načina plaćanja','Delayed account creation' => 'Odgođeno stvaranje računa','Address autocomplete with Google Maps APIs' => 'Automatsko dovršavanje adrese pomoću Google Maps API-ja','Multiple saved addresses with the address book' => 'Više spremljenih adresa s adresarom','EU-VAT assistant' => 'Asistent za PDV u EU','Hide this section' => 'Sakrij ovaj odjeljak','Learn more' => 'Saznajte više','Get early access' => 'Ostvarite rani pristup','Activate add-on' => 'Aktiviraj dodatak','Get more out of your checkout journey' => 'Izvucite više iz procesa plaćanja','Test API key' => 'Testni API ključ','Guided setup' => 'Vođeno postavljanje','Options' => 'Opcije','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Postavite izgled i dizajn <a href="%s">opcija na blagajni</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Omogućite gostu plaćanje i/ili pregledajte <a href="%s">postavke korisničkih računa</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Omogućite optimizirane stranice za plaćanje <a href="%1$s">košarice</a> , <a href="%2$s">zahvale</a> i <a href="%3$s">narudžbe</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Omogući <a href="%s">automatsko dovršavanje adrese</a> iz Google karata.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Omogućite više spremljenih adresa s <a href="%s">adresarom</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Provjerite postoje li dostupne <a href="%s">opcije integracije</a> za temu ili druge dodatke koje ste instalirali.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Dobijte bržu podršku i pomozite nam da poboljšamo kompatibilnost i izmjerimo utjecaj. <a href="%s">Omogućite praćenje korištenja</a> u postavkama alata.','Missing settings tab.' => 'Nedostaje kartica postavki.','Getting started' => 'Početak rada','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Odlično! Vaša stranica za naplatu sada radi na Fluid Checkoutu.</strong> Evo nekoliko koraka za početak:','Completed' => 'Završeno','Preview report data' => 'Pregled podataka izvješća','Send now' => 'Pošalji sada','Auto-detect' => 'Automatsko otkrivanje','Afrikaans' => 'Afrikanerski','Albanian' => 'Albanski','Amharic' => 'Amharski','Arabic' => 'arapski','Armenian' => 'Armenski','Azerbaijani' => 'Azerbajdžanski','Basque' => 'baskijski','Belarusian' => 'Bjeloruski','Bengali' => 'bengalski','Bosnian' => 'bosanski','Bulgarian' => 'bugarski','Burmese' => 'burmanski','Catalan' => 'katalonski','Chinese' => 'kineski','Chinese (Simplified)' => 'Kineski (pojednostavljeni)','Chinese (Hong Kong)' => 'kineski (Hong Kong)','Chinese (Traditional)' => 'Kineski (tradicionalni)','Croatian' => 'hrvatski','Czech' => 'češki','Danish' => 'danski','Dutch' => 'Nizozemski','English' => 'engleski','English (Australian)' => 'engleski (australski)','English (Great Britain)' => 'engleski (Velika Britanija)','Estonian' => 'estonski','Farsi' => 'Farsi','Finnish' => 'Finski','Filipino' => 'Filipinski','French' => 'francuski','French (Canadian)' => 'Francuski (kanadski)','Galician' => 'galicijski','Georgian' => 'gruzijski','German' => 'njemački','Greek' => 'grčki','Gujarati' => 'gudžaratski','Hebrew' => 'Hebrejski','Hindi' => 'Hindski','Hungarian' => 'Mađarski','Icelandic' => 'Islandski','Indonesian' => 'indonezijski','Italian' => 'talijanski','Japanese' => 'japanski','Kannada' => 'Kannadski','Kazakh' => 'Kazaški','Khmer' => 'Kmerski','Korean' => 'korejski','Kyrgyz' => 'Kirgizi','Lao' => 'Lao','Latvian' => 'Latvijski','Lithuanian' => 'litvanski','Macedonian' => 'makedonski','Malay' => 'malajski','Malayalam' => 'Malajalamski','Marathi' => 'Marathi','Mongolian' => 'mongolski','Nepali' => 'Nepalski','Norwegian' => 'Norveški','Polish' => 'Polirati','Portuguese' => 'portugalski','Portuguese (Brazil)' => 'Portugalski (Brazil)','Portuguese (Portugal)' => 'Portugalski (Portugal)','Punjabi' => 'Pandžapski','Romanian' => 'Rumunjski','Russian' => 'ruski','Serbian' => 'Srpski','Sinhalese' => 'Sinhalski','Slovak' => 'slovački','Slovenian' => 'slovenski','Spanish' => 'španjolski','Spanish (Latin America)' => 'Španjolski (Latinska Amerika)','Swahili' => 'Svahili','Swedish' => 'švedski','Tamil' => 'Tamil','Telugu' => 'Telugu','Thai' => 'Tajlandski','Turkish' => 'turski','Ukrainian' => 'ukrajinski','Urdu' => 'urdu','Vietnamese' => 'vijetnamski','Zulu' => 'zulu','Google address autocomplete' => 'Automatsko dovršavanje Google adrese','Google Places API version' => 'Verzija API-ja za Google mjesta','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Odaberite koju verziju Google Places API-ja želite koristiti. Preporučujemo da što prije prijeđete na novi Places API.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Preporučujemo korištenje &quot;Places API-ja (novo)&quot; od 1. ožujka 2025. Google će premjestiti verziju &quot;Places API-ja (naslijeđeno)&quot; u status naslijeđene verzije, što znači da više nećete moći omogućiti ovu uslugu za nove API ključeve i da ta verzija API-ja na kraju više neće biti dostupna. Postojeći računi koji već koriste naslijeđeni API mogu nastaviti raditi bez prekida.','(Recommended)' => '(Preporučeno)','Google API key' => 'Ključ Google API-ja','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Zalijepite svoj Google API ključ i upotrijebite testni gumb kako biste potvrdili da radi za ovu web stranicu. Provjerite je li ključ važeći i dopušten za vašu domenu, inače bi se polje za adresu moglo blokirati, što bi spriječilo kupce da dovrše svoje narudžbe.','Enable Google address autocomplete' => 'Omogući automatsko dovršavanje Google adrese','Enable address autocompletion using the Google Maps APIs.' => 'Omogućite automatsko dovršavanje adrese pomoću Google Maps API-ja.','Google API language' => 'Jezik Google API-ja','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ovaj će se jezik koristiti za prikaz prijedloga adresa API-ja za Google mjesta, a adrese će se također automatski dovršavati na ovom jeziku.','Result types' => 'Vrste rezultata','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Ostavite prazno za prihvaćanje bilo koje vrste rezultata, što obično daje bolje rezultate podudaranja. <a href="%s" target="_blank">Za više detalja pogledajte dokumentaciju</a> .<br> Odaberite do 5 vrsta rezultata pretraživanja adresa za vraćanje u poljima za automatsko dovršavanje adresa.<br> Posjetite dokumentaciju Google karata kako biste saznali više o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podržanim vrstama</a> .','Result types (Legacy API)' => 'Vrste rezultata (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Koju vrstu rezultata pretraživanja adresa vratiti prilikom korištenja Places API-ja (Legacy).<br> Posjetite dokumentaciju za Legacy Google Places API kako biste saznali više o <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">podržanim vrstama</a> .','Company fields' => 'Polja tvrtke','Enable autocomplete for the company name if available' => 'Omogući automatsko dovršavanje za naziv tvrtke ako je dostupno','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Omogući automatsko dovršavanje polja tvrtke s podacima o nazivu tvrtke kada se vrati iz Google Maps API-ja.','Business search' => 'Pretraga tvrtki','Enable search for businesses in the company field' => 'Omogući pretraživanje tvrtki u polju tvrtke','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Omogući predlaganje adresa povezanih s tvrtkom prilikom upisivanja u polje tvrtke, a zatim automatsko dovršavanje svih polja za adrese kada se tvrtka odabere iz prijedloga.','Company result types' => 'Vrste rezultata tvrtke','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Odaberite do 5 vrsta rezultata pretraživanja adresa koje će se vratiti u poljima tvrtke za automatsko dovršavanje.<br> Preporučena vrijednost je <code>establishment</code> , što uključuje većinu vrsta poduzeća.<br> Ostavite prazno kako biste prihvatili bilo koju vrstu rezultata, uključujući rezultate koji nisu povezani s tvrtkama.<br> Posjetite dokumentaciju Google karata kako biste saznali više o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podržanim vrstama</a> .','Google logo' => 'Googleov logotip','Show text and logo "Powered by Google"' => 'Prikaži tekst i logotip &quot;Pokreće Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kada je označeno, tekst i logotip &quot;Powered by Google&quot; prikazivat će se na dnu okvira za prijedloge automatskog dovršavanja adrese.','Brasil API address autocomplete' => 'Automatsko dovršavanje adrese za Brazil API','Brasil API' => 'Brazilski API','Enable Brasil API address autocomplete for CEP fields' => 'Omogući automatsko dovršavanje adrese Brasil API-ja za CEP polja','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Koristite Brasil API za dohvaćanje i automatsko popunjavanje adresa pomoću polja CEP/Poštanski broj. Relevantno samo za brazilske adrese.','API version' => 'Verzija API-ja','Choose which version of the Brasil API CEP method to use.' => 'Odaberite koju verziju metode Brasil API CEP želite koristiti.','Address book migration' => 'Migracija adresara','WooCommerce addresses' => 'WooCommerce adrese','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopirajte postojeće adrese za dostavu i naplatu iz WooCommercea u adresar kupaca.','Enable the address book feature' => 'Omogući funkciju adresara','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Omogućite kupcima spremanje više adresa i definiranje zadane adrese koja će se koristiti za dostavu i naplatu.','Address labels' => 'Oznake adresa','Allow customers to add a custom label for each address' => 'Omogućite korisnicima dodavanje prilagođene oznake za svaku adresu','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Naljepnice s adresama olakšavaju kupcima razlikovanje spremljenih adresa (npr. &quot;Mamina kuća&quot;). Naljepnice s adresama privatne su za kupce i neće se prikazivati ili ispisivati na stranici s detaljima narudžbe ili računima.','Display layout' => 'Raspored prikaza','Choose how saved addresses are displayed at checkout and on the cart.' => 'Odaberite kako će se spremljene adrese prikazivati prilikom plaćanja i u košarici.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Primjenjuje se prilikom plaćanja i u košarici. Spremljene adrese na stranici računa uvijek koriste izgled kartica.','Address cards' => 'Kartice s adresama','Address list' => 'Popis adresa','Dropdown field' => 'Padajuće polje','Address search' => 'Pretraga adresa','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Prikaži filter za pretraživanje adresa na frontendu kada korisnik ima barem ovaj broj spremljenih adresa na raspolaganju.','Not used when display layout is set to dropdown field.' => 'Ne koristi se kada je raspored prikaza postavljen na padajuće polje.','Addresses' => 'Adrese','Enable cart page optimizations to see more options' => 'Omogućite optimizacije stranice košarice da biste vidjeli više opcija','Sticky order summary' => 'Sažetak ljepljive narudžbe','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Odaberite poziciju za prikaz odjeljka s kuponima na stranici košarice. Primjenjivo samo kada je AJAX košarica omogućena i ako je korištenje kupona omogućeno u postavkama WooCommercea.','Layout of cross-sell' => 'Raspored unakrsne prodaje','Cross-sells displayed' => 'Prikazane unakrsne prodaje','Items' => 'Stavke','Cart page optimization' => 'Optimizacija stranice košarice','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Dajte svojoj košarici isti jasan, na konverziju usmjeren izgled kao i vašoj blagajni.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Uskladite izgled košarice sa stranicom za naplatu za dosljedan proces kupnje.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Košarica se uvijek ažurira u pozadini, bez ponovnog učitavanja cijele stranice kada se količine promijene.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Postavite kupone, dostavu i unakrsnu prodaju točno tamo gdje ostvaruju najbolju konverziju.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Sažetak narudžbe neka bude vidljiv tijekom pomicanja i dodajte simbole povjerenja tamo gdje kupcima treba utjeha.','Columns' => 'Kolumne','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Opći stilovi za korake naplate, sažetak narudžbe i ostale odjeljke. Odnosi se na ostale stranice za naplatu, košaricu, zahvalu (narudžba primljena) i pregled narudžbe.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Prilikom korištenja rasporeda <em>&quot;1 stupac&quot;</em> s predloškom dizajna <em>&quot;Podijeljeno&quot;</em> , desni stupac prikazuje se samo ako je aktivno područje widgeta bočne trake stranice (bočna traka blagajne, bočna traka košarice ili bočna traka primljene narudžbe). Inače stranica ostaje kao jedan stupac sa stilovima podjele.','Split column background' => 'Pozadina podijeljenog stupca','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Odaberite boju pozadine za sekundarni stupac Podijeljeni dizajn. Ostavite prazno za korištenje boje pozadine sažetka narudžbe.','Page templates' => 'Predlošci stranica','Checkout template' => 'Predložak za naplatu','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Preporučuje se za manje ometanja prilikom plaćanja. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Pročitajte istraživanje o napuštanju košarice</a> .','Sticky progress bar' => 'Ljepljiva traka napretka','Progress bar style' => 'Stil trake napretka','Order totals' => 'Ukupni iznosi narudžbi','Background color' => 'Boja pozadine','Action link' => 'Veza za akciju','Mobile order summary' => 'Sažetak mobilne narudžbe','Mobile initial state' => 'Početno stanje mobilnog uređaja','Enable editing cart items at checkout' => 'Omogući uređivanje artikala košarice prilikom plaćanja','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Omogućite kupcima da promijene količine proizvoda ili uklone artikle izravno na stranici za naplatu.','Cart item errors' => 'Pogreške u stavkama košarice','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Primjenjivo samo kada je kod kupona prikazan kao zaseban odjeljak na stranicama za naplatu ili košaricu i ako je korištenje kodova kupona omogućeno u postavkama WooCommercea.','Coupon codes position' => 'Pozicija kuponskih kodova','Apply coupon button' => 'Gumb Primijeni kupon','Select style of the "apply coupon" button.' => 'Odaberite stil gumba &quot;primijeni kupon&quot;.','Address line 2' => 'Adresa, redak 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ova se postavka dijeli između odjeljaka Blagajna i Lokalno preuzimanje. U odjeljku Lokalno preuzimanje također određuje hoće li se birač Dostava/Preuzimanje prikazivati unutar odjeljka za način dostave (prije adrese) ili kao zaseban odjeljak (poslije).','Customer accounts' => 'Računi kupaca','Guest checkout' => 'Odjava gosta','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Opcije za gostujuću naplatu, prijavu i stvaranje računa na stranici postavki WooCommerce računa. Ovdje se upravljaju radi vaše udobnosti, tako da možete koristiti različite vrijednosti po profilu postavki.','Allow customers to checkout without an account' => 'Omogućite kupcima plaćanje bez računa','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da kreiraju račun ili se prijave tijekom plaćanja, što može smanjiti stope konverzije.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kada je onemogućeno, kupci se moraju prijaviti ili kreirati račun kako bi dovršili kupnju.','Login at checkout' => 'Prijava prilikom plaćanja','Enable log-in during checkout' => 'Omogući prijavu tijekom plaćanja','Show a link for returning customers to log in from the checkout page.' => 'Prikažite poveznicu za prijavu stalnim kupcima sa stranice za naplatu.','Account creation' => 'Izrada računa','Allow customers to create an account during checkout' => 'Omogućite kupcima stvaranje računa tijekom plaćanja','Customers can create an account before placing their order.' => 'Kupci mogu kreirati račun prije nego što naruče.','Allow customers to create an account from the My account page' => 'Omogućite korisnicima stvaranje računa sa stranice Moj račun','Customers can register a new account from the My account page.' => 'Korisnici mogu registrirati novi račun na stranici Moj račun.','Username' => 'Korisničko ime','Generate from customer\'s name' => 'Generiraj iz imena kupca','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da odaberu korisničko ime tijekom plaćanja, što može smanjiti stope konverzije.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Korisničko ime se generira iz imena korisnika ili iz adrese e-pošte kada se ime ne može koristiti.','Password' => 'Lozinka','Send password setup link' => 'Pošalji poveznicu za postavljanje lozinke','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da postave lozinku tijekom plaćanja, što može smanjiti stope konverzije.','Customers receive an email to create their password securely.' => 'Korisnici primaju e-poštu za sigurno kreiranje lozinke.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Omogućite registriranim kupcima da dovrše naplatu bez prijave i povežu narudžbu s njihovim postojećim računom kada se kontaktni podaci podudaraju.','Existing account message' => 'Poruka o postojećem računu','Let customers create an account after placing their order, from the thank you page.' => 'Omogućite kupcima da kreiraju račun nakon što naruče, sa stranice zahvale.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Opcije u ovom odjeljku dostupne su kada su omogućeni gostujući račun i usklađivanje računa. Omogućite obje značajke iznad za konfiguriranje odgođenog stvaranja računa.','Enable delayed account creation' => 'Omogući odgođeno stvaranje računa','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Omogući odgođeno stvaranje računa kada su omogućeni i gostujuća naplata i usklađivanje računa.','Section position' => 'Položaj sekcije','Before customer details section' => 'Prije odjeljka s podacima o kupcu','After customer details section' => 'Nakon odjeljka s podacima o kupcu','Account creation benefits' => 'Prednosti kreiranja računa','Leaving the field empty will display the default text.' => 'Ako polje ostavite praznim, prikazat će se zadani tekst.','Inline buttons' => 'Ugrađeni gumbi','Required fields' => 'Obavezna polja','Enable gift message fields at checkout' => 'Omogući polja za poruku poklona prilikom plaćanja','Expanded gift message' => 'Proširena poruka uz poklon','Display gift message field always expanded' => 'Polje za poruku poklona uvijek je prošireno','Gift message in order details' => 'Poruka za poklon u detaljima narudžbe','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Trenutno nema dostupnih integracija u ovom odjeljku. Opcije povezane sa svakim dodatkom i temom pojavit će se ovdje samo kada je taj dodatak ili tema aktiviran.','Phone fields' => 'Polja za telefon','Field visibility' => 'Vidljivost polja','Field position' => 'Pozicija na terenu','Phone country code & validation' => 'Pozivni broj zemlje i validacija','Country' => 'Zemlja','Enable country on phone fields' => 'Omogući državu u poljima za telefon','Filter countries for shipping or billing' => 'Filtrirajte zemlje za dostavu ili naplatu','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Ograničite birač država u svakom polju telefona na države dopuštene za dostavu ili naplatu u vašoj trgovini.','Validation' => 'Validacija','Enable simple validation based on country rules' => 'Omogući jednostavnu validaciju na temelju pravila zemlje','Checks that the phone number is valid for the selected country, including country code and length.' => 'Provjerava je li telefonski broj važeći za odabranu zemlju, uključujući pozivni broj zemlje i duljinu.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Stroža provjera je li broj važeći mobilni, fiksni ili neki drugi prihvaćeni tip za odabranu zemlju. Moguće je da će neki važeći brojevi biti odbijeni.','Validation types' => 'Vrste validacije','Placeholders' => 'Rezervirana mjesta','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Trenutno nema licencnih ključeva za upravljanje. Licencni ključevi će se ovdje pojaviti kada je aktivan licencirani dodatak ili dodatak za Fluid Checkout.','Default delivery type' => 'Zadana vrsta isporuke','Choose which delivery type will be selected by default.' => 'Odaberite koja će vrsta isporuke biti odabrana prema zadanim postavkama.','Shipping zone fields' => 'Polja zone dostave','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Odaberite koja će se polja prikazivati za polja filtra za lokalnu zonu dostave preuzimanja. Ostavite prazno za prikaz svih dostupnih opcija.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ova će se polja prikazati kao filter za lokalne načine dostave preuzimanja. Neka se polja mogu i dalje prikazivati prilikom plaćanja ako nisu ovdje odabrana, ako kompatibilni dodaci zahtijevaju njihov ispravan rad.','Order shipping address' => 'Adresa za dostavu narudžbe','Order pay page optimization' => 'Optimizacija stranice za plaćanje narudžbe','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Neplaćenim narudžbama dajte isti jasan, na konverziju usmjeren izgled kao i prilikom plaćanja.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizirajte izgled stranice za plaćanje narudžbe za narudžbe koje čekaju na plaćanje.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Uskladite iskustvo plaćanja narudžbe s plaćanjem za dosljedan proces kupnje.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Dodajte simbole povjerenja i značke tamo gdje kupcima treba uvjeravanje prije plaćanja.','Thank you page optimization' => 'Optimizacija stranice s hvalama','Make the thank you page and order details clearer for customers after they buy.' => 'Učinite stranicu zahvale i detalje narudžbe jasnijima za kupce nakon što kupe.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizirajte stranicu zahvale i detalje narudžbe računa jasnijim izgledom.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Prikažite napredak statusa narudžbe, radnje, preuzimanja i bilješke gdje je to smisleno.','Customize order details sections on email notifications.' => 'Prilagodite odjeljke s detaljima narudžbe u obavijestima e-poštom.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Dodajte simbole povjerenja i značke tamo gdje kupcima treba uvjeravanje nakon kupnje.','Email notifications' => 'Obavijesti e-poštom','Enable thank you page and order details optimizations to see more options' => 'Omogućite optimizacije stranice zahvale i detalja narudžbe kako biste vidjeli više opcija','Use wide layout on thank you page' => 'Koristite široki raspored na stranici zahvale','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ove opcije utječu na stranicu zahvale, pregled detalja narudžbe na stranicama računa i na obavijesti e-poštom.','Save settings' => 'Spremi postavke','Docs' => 'Dokumenti','Cart' => 'Košarica','Thank you' => 'Hvala','Address autocomplete' => 'Automatsko dovršavanje adrese','Trust badges' => 'Značke povjerenja','You do not have permission to save these settings.' => 'Nemate dopuštenje za spremanje ovih postavki.','Invalid save request.' => 'Nevažeći zahtjev za spremanje.','Your settings have been saved.' => 'Vaše su postavke spremljene.','Saving...' => 'Spremanje...','Settings could not be saved. Please try again.' => 'Postavke nisu spremljene. Pokušajte ponovno.','Dismiss notice' => 'Odbaci obavijest','Open settings menu' => 'Otvori izbornik postavki','Close settings menu' => 'Zatvori izbornik postavki','Preview' => 'Pregled','Expand preview' => 'Proširi pregled','Collapse preview' => 'Sažmi pregled','Show header and footer' => 'Prikaži zaglavlje i podnožje','Hide header and footer' => 'Sakrij zaglavlje i podnožje','Page preview' => 'Pregled stranice','Preview viewport' => 'Pregled prikaznog polja','Tablet' => 'Tableta','Desktop' => 'Stolno računalo','Preview width' => 'Širina pregleda','Decrease width' => 'Smanji širinu','Preview width in pixels' => 'Širina pregleda u pikselima','Increase width' => 'Povećaj širinu','Preview as' => 'Pregledaj kao','Guest' => 'Gost','Logged in' => 'Prijavljen','Preview page' => 'Pregled stranice','Expand preview for a closer look' => 'Proširite pregled za bolji pogled','Available with %s.' => 'Dostupno uz %s.','Turn them on' => 'Uključite ih','Optimizations for this page are turned off. %s to preview the page.' => 'Optimizacije za ovu stranicu su isključene. %s za pregled stranice.','%s preview' => '%s pregled','Isolated session · nothing is saved' => 'Izolirana sesija · ništa nije spremljeno','Usage tracking' => 'Praćenje korištenja','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Šaljite neosjetljiva izvješća o okruženju web-mjesta kako biste pomogli Fluid Checkoutu da poboljša kompatibilnost. Izvješća se ne šalju dok se ne omoguće u opcijama u nastavku.','Send usage tracking reports to Fluid Checkout' => 'Pošaljite izvješća o praćenju korištenja Fluid Checkoutu','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ova izvješća nam pomažu poboljšati kompatibilnost i podršku za vašu web-lokaciju i šalju se tjedno kada su omogućena.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Izvješća ne uključuju podatke o kupcima, administratorima ili bilo koje druge osjetljive podatke.','Basic environment info' => 'Osnovne informacije o okruženju','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Podaci o WordPressu, PHP-u, WooCommerceu, temama i popisima dodataka. Uvijek uključeno kada je omogućeno izvještavanje. Pomaže nam da razumijemo okruženje u kojem se vaša web-lokacija izvodi.','Plugin settings' => 'Postavke dodatka','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Šalje postavke dodatka Fluid Checkout kako bi nam pomogao sa zahtjevima za podršku i pomogao nam da razumijemo kako koristite naše dodatke.','Coming soon' => 'Uskoro','Sales metrics' => 'Prodajni pokazatelji','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Mjesečni broj narudžbi i ukupna prodaja za godinu dana prije instaliranja Fluid Checkout-a do danas. Pomaže nam da shvatimo zarađujete li više novca s instaliranim našim dodacima. Nikada se ne šalju nikakvi podaci o kupcima ili korisnicima.','Utilities' => 'Komunalne usluge','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Koristite <code>TomSelect</code> komponente padajućeg izbornika umjesto <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect je jednostavnija komponenta za odabir iz padajućeg izbornika koja je manje sklona greškama od Select2, a nudi istu funkcionalnost.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Postavlja veličinu fonta unutar polja obrasca na 16px na stranicama optimiziranim ovim dodatkom kako bi se izbjeglo automatsko zumiranje prilikom interakcije s poljima obrasca na malim uređajima.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari i drugi preglednici mogu automatski zumirati na mobilnim uređajima kako bi tekst bio lakše čitljiv kada je veličina fonta manja od 16px.','Enable script processing tracking on the browser console.' => 'Omogućite praćenje obrade skripti u konzoli preglednika.','Unminified assets' => 'Neminificirana sredstva','Google Maps scripts' => 'Skripte za Google karte','Do not remove duplicate Google Maps scripts' => 'Ne uklanjajte duplicirane skripte Google karata','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kada je omogućeno, duplicirane skripte Google karata NEĆE se ukloniti, što može uzrokovati pogreške i probleme s performansama. Ovu opciju koristite samo prilikom rješavanja problema.','Widget areas' => 'Područja widgeta','Last step on mobile' => 'Posljednji korak na mobitelu','Display widgets only at last step on mobile' => 'Prikaži widgete samo u zadnjem koraku na mobilnom uređaju','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Prikaži widgete za značku povjerenja prilikom plaćanja samo prilikom pregleda posljednjeg koraka plaćanja na mobilnim uređajima','Standard' => 'Standard','VAT number field' => 'Polje za PDV broj','Add a VAT number field to the billing form.' => 'Dodajte polje za PDV broj u obrazac za naplatu.','Field label' => 'Oznaka polja','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Postavite oznaku polja PDV broja (npr. PDV broj). Na višejezičnim web stranicama bolje je ostaviti ovo polje praznim i prevesti izvorni niz.','VAT Number' => 'PDV broj','EU-VAT' => 'PDV EU','Enable the VAT number field to see more options' => 'Omogućite polje PDV broja za prikaz više opcija','VAT validation' => 'Potvrda PDV-a','Validate VAT number field for EU-VAT during checkout' => 'Potvrdite polje PDV broja za EU-PDV prilikom plaćanja','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Provjerava je li navedeni PDV broj važeći PDV broj registriran u europskoj VIES bazi podataka (Sustav razmjene informacija o PDV-u).','Shop VAT number' => 'PDV broj trgovine','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'PDV broj trgovine koji se koristi za zahtjev za validaciju EU-PDV-a i ispisuje se na računima.<br> <strong>Toplo preporučujemo da dodate PDV broj svoje trgovine</strong> jer u suprotnom rezultati VIES konzultacija možda neće biti valjani u računovodstvene svrhe.<br> Odnosno: <code>ATU99999999</code> ili <code>EE999999999</code> .','Reverse charge' => 'Obrnuta naplata','Apply reverse charge mechanism' => 'Primijenite mehanizam obrnutog oporezivanja','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Postavite poreznu stopu na nulu i prikažite &quot;Obrnuto naplaćivanje&quot; na računima kada je PDV broj kupca važeći. Ovisno o zemlji trgovine, može biti potreban drugačiji tekst &quot;Obrnuto naplaćivanje&quot;.','Same country' => 'Ista zemlja','Apply reverse charge mechanism for transactions in the shop country:' => 'Primijenite mehanizam obrnutog oporezivanja za transakcije u zemlji trgovine:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Omogućuje primjenu mehanizma obrnutog oporezivanja za transakcije između tvrtki u istoj zemlji kao i trgovina.','Reverse charge exceptions' => 'Iznimke obrnutog oporezivanja','Select additional countries to skip applying the reverse charge mechanism.' => 'Odaberite dodatne zemlje za koje želite preskočiti primjenu mehanizma obrnutog oporezivanja.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Porezi će se naplaćivati na narudžbe iz ovih zemalja čak i kada je naveden važeći PDV broj.','Reverse charge label on invoices' => 'Oznaka obrnutog naplata na računima','Set the label of "reverse charge" on the checkout page and order details.' => 'Postavite oznaku &quot;obrnuto naplaćivanje&quot; na stranici za plaćanje i u detaljima narudžbe.','Reverse charge text on invoices' => 'Tekst obrnutog naplata na fakturama','Set the label of "reverse charge" text on invoices.' => 'Postavite oznaku teksta &quot;obrnuto naplaćivanje&quot; na fakture.','Tax to be paid on reverse charge basis' => 'Porez koji se plaća na temelju obrnutog oporezivanja','Company name' => 'Naziv tvrtke','Autocomplete company name from VAT number' => 'Automatsko dovršavanje naziva tvrtke iz PDV broja','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Unesite naziv tvrtke za naplatu na temelju važećeg PDV broja koji je dostavio kupac.','Company name editing' => 'Uređivanje naziva tvrtke','Allow editing of auto-filled company name' => 'Dopusti uređivanje automatski unesenog naziva tvrtke','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kada je omogućeno, korisnici mogu promijeniti naziv tvrtke povezan s navedenim PDV brojem.','EU-VAT for digital goods' => 'PDV EU za digitalnu robu','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Od 1. siječnja 2015. uvedene su izmjene propisa EU o PDV-u koje se odnose na digitalnu robu, a koje utječu isključivo na B2C transakcije. PDV na digitalnu robu mora se izračunati na temelju lokacije kupca, a za to je potrebno prikupiti dokaze (IP adresu i adresu za naplatu).','Tax classes for digital goods' => 'Porezne klase za digitalnu robu','Select some tax classes' => 'Odaberite neke porezne klase','Location evidence' => 'Dokazi o lokaciji','Collect customer\'s location evidence' => 'Prikupite dokaze o lokaciji kupca','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Sprema IP adresu i provjerava je u odnosu na adresu za naplatu kupca. Kupci moraju potvrditi svoju adresu za naplatu označavanjem potvrdnog okvira na stranici za naplatu ako se država s adrese za naplatu i IP adrese ne podudaraju.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ova se opcija upravlja u Fluid Checkoutu. <a href="%s">Promijenite je u postavkama korisničkih računa</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ovom se opcijom upravlja u Fluid Checkoutu. Promijenite je pod Fluid Checkout &gt; Računi kupaca.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ova se opcija upravlja u Fluid Checkoutu. Odredište dostave uvijek je postavljeno na &quot;Zadano na adresu dostave kupca&quot; kada je Fluid Checkout aktiviran. Kupci i dalje mogu navesti različite adrese za dostavu i naplatu tijekom plaćanja.<br><br> U <a href="%s">postavkama Fluid Checkout-a</a> dostupna je opcija za postavljanje zadane adrese za naplatu koja je ista kao i adresa za dostavu.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ova se opcija upravlja u Fluid Checkoutu. Odredište dostave uvijek je postavljeno na &quot;Zadano na adresu dostave kupca&quot; kada je Fluid Checkout aktiviran. Kupci i dalje mogu navesti različite adrese za dostavu i naplatu tijekom plaćanja.<br><br> Opcija za postavljanje zadane adrese za naplatu koja je ista kao i adresa za dostavu dostupna je u WooCommerce &gt; Postavke &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ove postavke su premještene u WP Admin &gt; Fluid Checkout &gt; Postavke.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ova kartica Postavke WooCommercea je zastarjela i bit će uklonjena u Fluid Checkoutu 6.0.','Go to settings page' => 'Idi na stranicu postavki','Hide this tab permanently' => 'Trajno sakrij ovu karticu','Site report preview' => 'Pregled izvješća o web-lokaciji','This is the data that would be included in the next site environment report based on your current settings.' => 'Ovo su podaci koji bi bili uključeni u sljedeće izvješće o okruženju web-mjesta na temelju vaših trenutnih postavki.','Loading report preview...' => 'Učitavanje pregleda izvješća...','Could not load the site report preview. Try again.' => 'Nije moguće učitati pregled izvješća o web-lokaciji. Pokušajte ponovno.','Could not send the site report. Try again.' => 'Nije moguće poslati izvješće o lokaciji. Pokušajte ponovno.','Site report sent successfully.' => 'Izvješće o lokaciji uspješno poslano.','Enable and send now' => 'Omogući i pošalji odmah','Close' => 'Zatvoriti','A site report request is already in progress. Try again in a moment.' => 'Zahtjev za izvješće o lokaciji već je u tijeku. Pokušajte ponovno za trenutak.','Site environment reporting is disabled.' => 'Izvješćivanje o okruženju web-mjesta je onemogućeno.','No site report data is available to send.' => 'Nema dostupnih podataka izvješća o lokaciji za slanje.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ova domena web-mjesta ne može slati izvješća o okruženju (lokalne ili razvojne domene su isključene).','A site report was sent recently. Try again later.' => 'Izvješće o lokaciji je nedavno poslano. Pokušajte ponovno kasnije.','The site report could not be sent. Try again later.' => 'Izvješće o lokaciji nije moguće poslati. Pokušajte ponovno kasnije.','Site environment reporting is not available.' => 'Izvješćivanje o okruženju web-mjesta nije dostupno.','No site report data is available for the selected settings.' => 'Za odabrane postavke nisu dostupni podaci izvješća o web-lokaciji.','You are not allowed to manage site reports.' => 'Nije vam dopušteno upravljanje izvješćima web-mjesta.','PRO feature' => 'PRO značajka','Other plugins' => 'Ostali dodaci','Get only this add-on &mdash; %s' => 'Nabavite samo ovaj dodatak — %s','Install add-on' => 'Instaliraj dodatak','Upgrade to PRO &mdash; %s' => 'Nadogradite na PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Nabavite %2$s</a> da biste otključali ove opcije.','Add-on' => 'Dodatak','View documentation' => 'Prikaži dokumentaciju','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Zahtjevi zahtijevaju prijavljenog WordPress korisnika. Izostavite user_id da biste koristili podatke trenutnog korisnika ili proslijedite user_id za ciljanje drugog računa kada pozivatelj može uređivati tog korisnika (mogućnost edit_user). Neautentificirani zahtjevi vraćaju fc_api_forbidden. Nevažeći user_id vraća fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 s { &quot;data&quot;: { ... } } kada rukovatelj vrati korisni teret.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 s { &quot;success&quot;: true } kada nema korisnog tereta (na primjer DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Neuspjesi vraćaju WordPress REST pogrešku JSON iz WP_Error (kod, poruka, data.status). Žičani kodovi koriste prefiks fc_api_*.','Forbidden access.' => 'Zabranjen pristup.','Target user was not found.' => 'Ciljani korisnik nije pronađen.','This feature is not available.' => 'Ova značajka nije dostupna.','A required address field is missing.' => 'Nedostaje obavezno polje za adresu.','Postcode or ZIP is invalid.' => 'Poštanski broj nije važeći.','Phone number is invalid.' => 'Broj telefona nije važeći.','State or county is invalid.' => 'Država ili županija nije važeća.','Country is invalid or has no address fields.' => 'Država je nevažeća ili nema polja za adresu.','The request could not be processed.' => 'Zahtjev nije mogao biti obrađen.','Back to previous step' => 'Natrag na prethodni korak','Skip to settings' => 'Preskoči na postavke','Start over and return to the first guided setup step' => 'Počnite ispočetka i vratite se na prvi korak vođenog postavljanja','Start over' => 'Počni ispočetka','Please complete all sub-steps before continuing.' => 'Molimo vas da dovršite sve podkorake prije nego što nastavite.','Expand' => 'Proširiti','Collapse' => 'Kolaps','Skip' => 'Preskočiti','Mark as complete' => 'Označi kao dovršeno','Mark as incomplete' => 'Označi kao nedovršeno','View full-size image: %s' => 'Prikaži sliku u punoj veličini: %s','Full-size setup guide image' => 'Slika vodiča za postavljanje u punoj veličini','Close image' => 'Zatvori sliku','Fluid Checkout Guided Setup' => 'Vođeno postavljanje Fluid Checkout-a','Welcome' => 'Dobrodošli','Explore your checkout' => 'Istražite svoju blagajnu','All set' => 'Sve je spremno','You do not have permission to access this page.' => 'Nemate dopuštenje za pristup ovoj stranici.','Go to step %1$d: %2$s' => 'Idi na korak %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ovaj vodič za postavljanje pomaže vam da se upoznate s Fluid Checkoutom. Koraci u nastavku su za sada samo okvirni.','Continue to the next step when you are ready.' => 'Nastavite na sljedeći korak kada budete spremni.','Open your store checkout to see Fluid Checkout in action.' => 'Otvorite blagajnu svoje trgovine kako biste vidjeli Fluid Checkout u akciji.','View checkout page' => 'Pogledajte stranicu za naplatu','You can return to Fluid Checkout settings to continue configuring your store.' => 'Možete se vratiti na postavke Fluid Checkout-a kako biste nastavili konfigurirati svoju trgovinu.','Review checkout and cart settings' => 'Pregled postavki naplate i košarice','Explore add-ons from the dashboard' => 'Istražite dodatke s nadzorne ploče','Finish & go to settings' => 'Završi i idi na postavke','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Ažurirajte opciju vidljivosti polja telefona za naplatu s naslijeđene vrijednosti kako bi odgovarala WooCommerce konvencijama.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Ažurirajte opciju vidljivosti polja telefona za dostavu s naslijeđene vrijednosti kako bi odgovarala WooCommerce konvencijama.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopirajte postavku boje pozadine sažetka narudžbe u novu opciju boje pozadine sekundarnog stupca Podijeljeni dizajn.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Poboljšana značajka odabira polja uvijek je onemogućena kada se koristi Biteship dodatak.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pozicija narudžbe uvijek je postavljena na &quot;Ispod sažetka narudžbe&quot; kada se koristi njemačko tržište. Taj dodatak zahtijeva da se gumb za narudžbu i pravni potvrdni okviri prikazuju ispod sažetka narudžbe.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Položaj narudžbe je uvijek postavljen na &quot;Ispod sažetka narudžbe&quot; kada se koristi Germanized za WooCommerce. Taj dodatak zahtijeva da se gumb za narudžbu i pravni potvrdni okviri prikazuju ispod sažetka narudžbe.','Edit pickup locations' => 'Uredi lokacije preuzimanja','Use local pickup label from WooCommerce settings' => 'Koristite lokalnu etiketu za preuzimanje iz postavki WooCommercea','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kada je omogućeno, oznaka opcije preuzimanja pri plaćanju odgovara naslovu iz postavki lokacije preuzimanja u WooCommerceu. Kada je onemogućeno, oznaka koristi prevodivi tekst &quot;Lokalno preuzimanje&quot; iz Fluid Checkout-a.','Button label for applying coupon codesApply' => 'primijeniti','Checkout step titleContact' => 'Kontakt','Checkout step titleShipping' => 'Dostava','Checkout step titleBilling' => 'Naplata','Checkout step titlePayment' => 'Plaćanje','Checkout substep change link labelChange' => 'Promijeniti','Checkout substep save link labelSave changes' => 'Spremite promjene','Substep review textNone.' => 'Nijedan.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nije odabrana slika.','Settings sectionCart' => 'Košarica','Settings sectionOrder pay' => 'Plaćanje naloga','Settings sectionThank you' => 'Hvala','Settings section titleIntegrations' => 'Integracije','Settings section titleLicense keys' => 'Ključevi licence','Captcha positionBefore place order section' => 'Prije naručivanja odjeljak','Captcha positionBefore place order button' => 'Gumb Prije naručivanja','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Zatvoriti','Log in link label at checkout contact stepLog in' => 'Prijavite se','Log in separator label at for when guest checkout is disabledOr continue below' => 'Ili nastavite u nastavku','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Ili nastavite kao gost','Clear image selection on admin pages.Remove image' => 'Ukloni sliku','shipping packagesShipping %d' => 'Dostava %d','shipping packagesShipping' => 'Dostava','Used as fallback for "Proceed to next step" button labelnext step' => 'sljedeći korak','Substep review checkbox valueYes' => 'Da','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Zahod','Dummy customer last name in the admin previewDoe' => 'Srna','Dummy customer company in the admin previewExample Company' => 'Primjer tvrtke','Dummy customer street address in the admin preview123 Main Street' => 'Glavna ulica 123','Dummy customer city in the admin previewAnytown' => 'Bilo koji grad','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Molimo vas da paket ostavite na ulaznim vratima.','Dummy product name in the admin previewBeanie' => 'Kapa','Dummy product name in the admin previewCap' => 'Kapa','Dummy product name in the admin previewT-Shirt' => 'Majica','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Primili smo vašu narudžbu i poslat ćemo vam ažuriranje kada bude poslana.','Dummy download in the admin previewUser guide' => 'Vodič za korisnike','Google Places API versionsPlaces API (New)' => 'API za mjesta (novo)','Google Places API versionsPlaces API (Legacy)' => 'API za mjesta (zastarjelo)','Brasil API versionsVersion 1' => 'Verzija 1','Brasil API versionsVersion 2' => 'Verzija 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Brža naplata sljedeći put ✔ Upravljajte postavkama plaćanja ✔ Pregledajte status i povijest narudžbe','VAT number field visibilityHidden' => 'Skriven','VAT number field visibilityOptional' => 'Izborno','VAT number field visibilityRequired' => 'Potreban','Delivery typeShipping to address' => 'Dostava na adresu','Delivery typeLocal pickup' => 'Lokalno preuzimanje',] ];